member.example:
This example shows how to perform specific actions immediately after the report layout has changed.

designer.LayoutChanged += (sender, args) => {
	// Example action: Log a message indicating the layout change.
	Console.WriteLine("The report layout has been changed.");
	// Additional actions can be performed here.
};

Use this event to handle report layout changes. The following example prevents the addition of new controls until the report has a data set:

designer.LayoutChanging += (sender, args) => {
	if (args.Type == LayoutChangeType.ControlAdd 
	&& designer.Report is PageReport pageReport 
	&& pageReport.Report.DataSets.Count == 0)
	{
		// Use the designer's service provider to get the IUIService and show an error message.
		((IUIService) designer).ShowError("Add data set first.");
		args.AllowChange = false; // Prevent the change.
	}
};

Utilize the specified event to supply data necessary for the preview functionality of page reports. This ensures that the report previews are populated with the latest data.

designer.LocateDataSource += (sender, args) => {
	var dataSourceName = args.DataSet.Query.DataSourceName;
	var dataSource = ((PageReport)designer.Report).Report.DataSources.First(x => x.Name == dataSourceName);
	if(dataSource.ConnectionProperties.DataProvider == "OBJECT")
	{
	    args.Data = new[] { new { CustomerName = "Gc Inc." } };
	}
};

It can be necessary for report preview. Use this event to provide the credentials for the data providers. 

designer.LocateCredentials += (sender, args) => {
	args.UserName = "sa";
	args.Password = "12345";
}

example.code:
// Subscribe to the ReportChanged event to react to changes in the report.
// For instance, enabling a 'Save' button to indicate that unsaved changes are present.
designer.ReportChanged += (sender, args) => {
saveButton.Enabled = true;
};

member.example:
Utilize the ActiveTabChanged event to respond to switches between the Script, Design, and Preview tabs. The ActiveTab property allows you to determine 
the currently active tab.

public partial class Form1 : Form
{
	public Form1()
	{
		InitializeComponent();
		designer = new Designer() { Dock = DockStyle.Fill };
		designer.ActiveTabChanged += (sender, args) => {
			//Get the currently editing report name.
			var reportName = designer.Report switch
			{
				PageReport pageReport => pageReport.Report.Name,
				SectionReport sectionReport => sectionReport.Name,
				_ => "Report"
			};
			//Set the form title to reflect the current designer state
			this.Text = designer.ActiveTab switch
			{
				DesignerTab.Script => $"{reportName} - Script",
				DesignerTab.Preview => $"{reportName} - Preview",
				_ => $"{reportName} - Edit"
			};
		};
		Controls.Add(designer);
	}
}

You can configure this property during the designer's initialization or set it later as needed.

// For example, you can add your own button to toggle the grid off:
void Button_OnClick(object sender, EventArgs e)
{
	designer.DrawGrid = false;
}
// Or you can enable it during the designer's initialization:
designer.DrawGrid = true;
// Note: the user can change the grid visibility using the buttons on the tool panel. You can restrict this by using the ‘ToolPanel’ property.

This property allows you to specify custom fonts for use in both the preview and design of reports. To utilize this feature, you must first define a custom font resolver:

//Custom font resolver
public sealed class DirectoryFontResolver : GrapeCity.ActiveReports.IFontResolver
{
	Documents.Text.FontCollection _fonts;
	public DirectoryFontResolver(string fontsDirectory)
	{
		_fonts = new Documents.Text.FontCollection();
		// load standard Windows fonts
		_fonts.RegisterDirectory(Environment.GetFolderPath(Environment.SpecialFolder.Fonts));
		// load fonts from custom directory
		_fonts.RegisterDirectory(fontsDirectory);
		_fonts.DefaultFont = _fonts.FindFamilyName("Arial");
	}
	Documents.Text.FontCollection IFontResolver.GetFonts(string familyName, bool isBold, bool isItalic)
	{
		var fonts = new Documents.Text.FontCollection();
		fonts.Add(_fonts.FindFamilyName(familyName, isBold, isItalic) ?? _fonts.DefaultFont);
		return fonts;
	}
}

After defining a custom font resolver, you can then associate it with the designer instance.

class MyDesignerForm : Form
{
	public MyDesignerForm()
	{
		InitializeComponent();
		//note the designer must be added to the form and its name have to be '_designer'.
		_designer.FontResolver = new DirectoryFontResolver("c:\\Fonts");
	}
}

You can disable certain actions for pages in page reports.

// Disable the action to add a new page.
designer.PageReportDesignerActions = PageReportDesignerActions.All ^ PageReportDesignerActions.AddPage

This example shows how to integrate the Designer component with a PropertyGrid in a Windows Forms application.

class MyForm : Form 
{
	MyForm()
	{
		var designer = new Designer() { Dock = DockStyle.Fill };
		var propertyGrid = new PropertyGrid { Dock = DockStyle.Right };
		designer.PropertyGrid = propertyGrid;
		Controls.Add(designer);
		Controls.Add(propertyGrid);
	}
}

This property allows you to define a custom resource locator for accessing resources such as images and subreports from a specific location, whether 
it's a custom storage solution or a particular directory on the disk. To utilize this feature, you must implement a custom resource locator. 
See the example below for guidance on implementation:

class MyResourceLocator : ResourceLocator
{
	public override Resource GetResource(ResourceInfo resourceInfo)
	{
		if (resourceInfo.Name == "redSquare.png")
		{
			//Here we draw the image with the red square in the center.
			//You can load the image from file system, or from data base, or from assembly resources.
			var img = new Bitmap(100, 100);
			using var graphics = Graphics.FromImage(img);
			using var redBrush = new SolidBrush(Color.Red);
			graphics.FillRectangle(redBrush, 10, 10, 80, 80);
			var tmpStream = new MemoryStream();
			img.Save(tmpStream, System.Drawing.Imaging.ImageFormat.Png);
			tmpStream.Position = 0;
			return new Resource(tmpStream, new Uri("redSquare.png", UriKind.Relative));
		}
		return new Resource();
	}
}

Then, you can utilize this custom resource locator within the designer.

class MyDesignerForm : Form
{
	public MyDesignerForm()
	{
		InitializeComponent();
		//note the designer must be added to the form and its name have to be '_designer'.
		_designer.ResourceLocator = new MyResourceLocator();
	}
}

This example demonstrates how to show or hide the data source icon in the section tab for section reports.

public partial class Form1 : Form
{
	Designer designer;
	public Form1()
	{
		InitializeComponent();
		designer = new Designer() { Dock = DockStyle.Fill };
		designer.NewReport(DesignerReportType.Section);
		designer.ShowDataSourceIcon = false;// Set to true to show the data source icon.
	}
}

This example illustrates how to add a Designer component and a Toolbox to a Windows Forms application, configuring the Toolbox as the Designer's toolbox.

class MyForm : Form
{
	MyForm()
	{
		var designer = new Designer() { Dock = DockStyle.Fill };
		var toolbox = new Toolbox { Dock = DockStyle.Right };
		designer.Toolbox = toolbox;
		Controls.Add(designer);
		Controls.Add(toolbox);
	}
}

Demonstrates how to control the availability of toolbox items in the designer's toolbox.

// First, define a state provider by implementing the IToolboxUser interface. This example enables only the BandedListDesigner tool.
class ToolboxStateProvider : IToolboxUser
{
	public bool GetToolSupported(ToolboxItem tool)
	{
		if (tool.TypeName == "GrapeCity.ActiveReports.Design.DdrDesigner.Designers.BandedList.BandedListDesigner")
			return true;
		return false;
	}
	public void ToolPicked(ToolboxItem tool) { }
}

Then, configure the toolbox with the state provider to control the enabled items.

toolbox.ConfigureToolboxItems(new ToolboxStateProvider());

This example shows how to remove a specific item from the toolbox. It demonstrates finding the item by its type name and then removing it.

private static void RemoveBandedListFromToolBox(Toolbox toolbox)
{
	// Find the item to be removed by its type name.
	var bandedList = toolbox.GetToolboxItems()
		.OfType<ToolboxItem>()
		.Single(items => items.TypeName.EndsWith("BandedListDesigner"));
	// Remove the found banded list item from the toolbox.
	toolbox.RemoveToolboxItem(items);
}

